const precio_unitario = 25000;
let error_log = null;

// 2. Extraer datos del Webhook
const webhookData = $('Webhook de Entrada').first().json.body || $('Webhook de Entrada').first().json;
let nombre = webhookData.nombre || "";
let telefono = webhookData.telefono || "";
let mensaje = webhookData.mensaje || "";

let ancho = null;
let alto = null;
let cantidad = 1;

// 3. Obtener dimensiones prioritarias del Webhook o de la IA
if (webhookData.ancho_cm !== undefined && webhookData.ancho_cm !== null && webhookData.ancho_cm !== '') {
    ancho = parseFloat(webhookData.ancho_cm);
    alto = parseFloat(webhookData.alto_cm);
    cantidad = parseInt(webhookData.cantidad || 1, 10);
} else {
    try {
        const aiOutput = $('Nodo de IA: Extraer Medidas').first().json;
        let aiData = {};

        if (typeof aiOutput === 'string') {
            aiData = JSON.parse(aiOutput);
        } else if (aiOutput.message && aiOutput.message.content) {
            const content = aiOutput.message.content;
            aiData = typeof content === 'string' ? JSON.parse(content) : content;
        } else if (aiOutput.text) {
            aiData = typeof aiOutput.text === 'string' ? JSON.parse(aiOutput.text) : aiOutput.text;
        } else {
            aiData = aiOutput;
        }

        ancho = aiData.ancho_cm !== undefined && aiData.ancho_cm !== null ? parseFloat(aiData.ancho_cm) : null;
        alto = aiData.alto_cm !== undefined && aiData.alto_cm !== null ? parseFloat(aiData.alto_cm) : null;
        cantidad = aiData.cantidad !== undefined && aiData.cantidad !== null ? parseInt(aiData.cantidad, 10) : 1;
    } catch (e) {
        error_log = "Error al leer datos del nodo de IA o no se ejecutó: " + e.message;
    }
}

// Estructura de respuesta por defecto
const responseData = {
    ok: true,
    encontrado: false,
    respuesta: "",
    cantidad_solicitada: isNaN(cantidad) ? 1 : cantidad,
    cantidad_disponible: 0,
    precio_unitario: precio_unitario,
    total_estimado: 0,
    productos: [],
    alternativas: [],
    error_log: error_log
};

// Caso D: Faltan medidas (ancho o alto no identificados)
if (ancho === null || alto === null || isNaN(ancho) || isNaN(alto)) {
    responseData.respuesta = "Para revisar el stock necesito la medida aproximada: ancho x alto, en centímetros. Ejemplo: 21 x 100 cm.";
    responseData.lead = {
        fecha_hora: new Date().toISOString(),
        mensaje: mensaje,
        nombre: nombre,
        telefono: telefono,
        ancho_solicitado_cm: ancho,
        alto_solicitado_cm: alto,
        cantidad_solicitada: responseData.cantidad_solicitada,
        encontrado: false,
        cantidad_disponible: 0,
        ids_encontrados: "",
        total_estimado: 0,
        respuesta_entregada: responseData.respuesta
    };
    return [ { json: responseData } ];
}

// 4. Leer filas de Google Sheets de forma segura
let rows = [];
try {
    const rawRows = $('Google Sheets: Leer Inventario').all();
    if (rawRows.length > 0 && rawRows[0].json.error) {
        throw new Error(rawRows[0].json.error.message || "Error en Google Sheets");
    }
    rows = rawRows.map(item => item.json);
} catch (e) {
    responseData.respuesta = "No pudimos revisar el inventario en este momento. Escríbenos por WhatsApp para confirmar disponibilidad.";
    responseData.error_log = "Error al leer Google Sheets: " + e.message;
    responseData.lead = {
        fecha_hora: new Date().toISOString(),
        mensaje: mensaje,
        nombre: nombre,
        telefono: telefono,
        ancho_solicitado_cm: ancho,
        alto_solicitado_cm: alto,
        cantidad_solicitada: responseData.cantidad_solicitada,
        encontrado: false,
        cantidad_disponible: 0,
        ids_encontrados: "",
        total_estimado: 0,
        respuesta_entregada: responseData.respuesta
    };
    return [ { json: responseData } ];
}

// 5. Filtrar inventario válido
const cleanInventory = rows.filter(row => {
    if (row.ancho_cm === undefined || row.alto_cm === undefined) return false;
    const unidades = parseInt(row.unidades || 0, 10);
    const estado = (row.estado || "").toLowerCase().trim();
    const isAgotado = estado.includes("agotado") || estado.includes("vendido") || estado.includes("no disponible");
    return unidades > 0 && !isAgotado;
});

// 6. Buscar coincidencia exacta (tolerancia +- 0.5 cm)
const exactMatches = cleanInventory.filter(row => {
    const rowAncho = parseFloat(row.ancho_cm);
    const rowAlto = parseFloat(row.alto_cm);
    return Math.abs(rowAncho - ancho) <= 0.5 && Math.abs(rowAlto - alto) <= 0.5;
});

const formatCurrency = (val) => {
    return "$" + val.toLocaleString("es-CL").replace(/,/g, ".");
};

if (exactMatches.length > 0) {
    const totalDisponibles = exactMatches.reduce((acc, row) => acc + parseInt(row.unidades || 0, 10), 0);
    const listadoProductos = exactMatches.map(row => ({
        id: row.id || "",
        tipo: row.tipo || "Fijo",
        medida_cm: row.medida_cm || `${row.ancho_cm} x ${row.alto_cm} cm`,
        unidades: parseInt(row.unidades || 0, 10),
        descripcion: row.descripcion || `Termopanel fijo ${row.ancho_cm} x ${row.alto_cm} cm`,
        rack: row.rack || ""
    }));

    responseData.encontrado = true;
    responseData.cantidad_disponible = totalDisponibles;
    responseData.productos = listadoProductos;

    const principalDesc = listadoProductos[0].descripcion;

    if (totalDisponibles >= responseData.cantidad_solicitada) {
        const totalEstimado = responseData.cantidad_solicitada * precio_unitario;
        responseData.total_estimado = totalEstimado;
        responseData.respuesta = `Sí, tenemos ${responseData.cantidad_solicitada} unidad(es) disponible(s) de ${principalDesc}. Valor estimado: ${formatCurrency(totalEstimado)}. Retiro coordinado en El Monte; no realizamos despachos. Escríbenos para coordinar disponibilidad final y retiro.`;
    } else {
        responseData.respuesta = `Tenemos ${totalDisponibles} unidad(es) disponibles de ${principalDesc}, pero solicitaste ${responseData.cantidad_solicitada}. Valor por unidad: ${formatCurrency(precio_unitario)}. Retiro coordinado en El Monte.`;
    }
} else {
    const alternatives = cleanInventory.map(row => {
        const rowAncho = parseFloat(row.ancho_cm);
        const rowAlto = parseFloat(row.alto_cm);
        const diffAncho = rowAncho - ancho;
        const diffAlto = rowAlto - alto;
        const distance = Math.sqrt(diffAncho * diffAncho + diffAlto * diffAlto);
        return { row, distance };
    });

    alternatives.sort((a, b) => a.distance - b.distance);

    const top3 = alternatives.slice(0, 3).map(alt => ({
        id: alt.row.id || "",
        tipo: alt.row.tipo || "Fijo",
        medida_cm: alt.row.medida_cm || `${alt.row.ancho_cm} x ${alt.row.alto_cm} cm`,
        unidades: parseInt(alt.row.unidades || 0, 10),
        descripcion: (alt.row.descripcion || `Termopanel fijo ${alt.row.ancho_cm} x ${alt.row.alto_cm} cm`) + " (medida similar, no exacta)",
        rack: alt.row.rack || ""
    }));

    responseData.alternativas = top3;
    responseData.respuesta = `No encontramos stock exacto de ${ancho} x ${alto} cm. Te mostramos medidas similares disponibles para que puedas revisarlas. Para una confirmación o combinación de medidas, contáctanos por WhatsApp.`;
}

// Generar objeto Lead listo para Google Sheets
responseData.lead = {
    fecha_hora: new Date().toISOString(),
    mensaje: mensaje,
    nombre: nombre,
    telefono: telefono,
    ancho_solicitado_cm: ancho,
    alto_solicitado_cm: alto,
    cantidad_solicitada: responseData.cantidad_solicitada,
    encontrado: responseData.encontrado,
    cantidad_disponible: responseData.cantidad_disponible,
    ids_encontrados: responseData.productos.map(p => p.id).join(', '),
    total_estimado: responseData.total_estimado,
    respuesta_entregada: responseData.respuesta
};

return [ { json: responseData } ];
